<?php if(($user['role']??'')==='teacher' && !empty($tasks)): ?><details class="card"><summary><strong>Manage activities and submission links</strong></summary><?php foreach($tasks as $task): ?><article class="card"><h3><?=View::e($task['title'])?></h3><form method="post" action="?route=task-update" class="grid"><?=View::csrfField()?><input type="hidden" name="task_id" value="<?=View::e($task['id'])?>"><label>Title<input name="title" value="<?=View::e($task['title'])?>" required></label><label>Description<textarea name="description"><?=View::e($task['description']??'')?></textarea></label><label>Deadline<input type="datetime-local" name="due_at" value="<?=!empty($task['due_at'])?View::e(date('Y-m-d\TH:i',strtotime($task['due_at']))):''?>"></label><label><input type="checkbox" name="submissions_open" value="1" <?=!isset($task['submissions_open'])||$task['submissions_open']?'checked':''?>> Accept submissions</label><button>Save activity</button></form></article><?php endforeach; ?></details><?php endif; ?><?php include __DIR__.'/announcement-visibility.php'; ?>
